const store = $getWorkflowStaticData('global');
const res = $input.first().json;
const status = res.status ?? 'error';

// ── Watch health, EDGE-triggered ────────────────────────────────────────────
// A revoked Google token or a broken Igor makes this watch silently blind,
// which is the failure mode worth waking SPEDA for. But only on the edge: at a
// 10-minute cadence, alerting every poll would turn one expired token into 144
// pushes a day.
if (status !== 'ok') {
  const wasBroken = Boolean(store.broken);
  store.broken = true;
  if (wasBroken) { return []; }
  return [{ json: {
    alert: true,
    status,
    detail: res.detail ?? res.message ?? '',
    count: 0,
    message_ids: [],
    messages: [],
  } }];
}
store.broken = false;

// ── The normal path ─────────────────────────────────────────────────────────
// Nothing from TDV. Return NO items: n8n stops the branch on an empty return,
// so no trigger call, no agentic turn, no tokens. This is what makes the whole
// workflow nearly free — it is the outcome ~99% of runs have.
if (!res.count) { return []; }

return [{ json: {
  alert: false,
  count: res.count,
  message_ids: res.message_ids ?? [],
  messages: res.messages ?? [],
} }];
